export interface ConnectorConfig {
  /** Mailchimp API key (Bearer token). Environment variable: MAILCHIMP_API_KEY */
  mailchimpApiKey: string;
  /** Mailchimp list ID (audience ID). Environment variable: MAILCHIMP_LIST_ID */
  mailchimpListId: string;
  /** Optional fetch implementation for testing or non-browser environments. */
  fetch?: typeof fetch;
  /** Tag name to add when a refund occurs. Defaults to "refunded". */
  tagName?: string;
}

export interface StripeChargeRefundedPayload {
  /** Stripe charge ID (e.g., "ch_1234567890"). Used as Idempotency-Key for the POST request. */
  id: string;
  customer: {
    /** Stripe customer ID (e.g., "cus_1234567890"). Used as the Mailchimp subscriber_hash. */
    id: string;
  };
}

export interface HandleResult {
  /** Whether the tag was actually added (false if it already existed). */
  tagAdded: boolean;
  /** The Stripe charge ID used as Idempotency-Key. */
  chargeId: string;
  /** The subscriber hash (Mailchimp member identifier) used in the request. */
  subscriberHash: string;
  /** The tag name that was checked/added. */
  tagName: string;
}

/**
 * Handles a Stripe `charge.refunded` webhook by adding a tag to the corresponding
 * Mailchimp subscriber. Skips the operation if the tag already exists on the subscriber.
 *
 * @param payload - The parsed Stripe webhook payload (charge.refunded event).
 * @param config - Connector configuration including Mailchimp credentials and list ID.
 * @returns Result indicating whether the tag was added and the identifiers used.
 * @throws Error if required payload fields are missing, config is incomplete, or Mailchimp API returns non-2xx.
 */
export async function handle(
  payload: StripeChargeRefundedPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required payload fields
  if (!payload.id) {
    throw new Error('Missing required field: id (Stripe charge ID)');
  }
  if (!payload.customer?.id) {
    throw new Error('Missing required field: customer.id (Stripe customer ID)');
  }

  const { mailchimpApiKey, mailchimpListId, fetch = globalThis.fetch, tagName = 'refunded' } = config;

  if (!mailchimpApiKey) {
    throw new Error('Missing config: mailchimpApiKey (set MAILCHIMP_API_KEY env var)');
  }
  if (!mailchimpListId) {
    throw new Error('Missing config: mailchimpListId (set MAILCHIMP_LIST_ID env var)');
  }
  if (typeof fetch !== 'function') {
    throw new Error('No fetch implementation available. Provide config.fetch or run in an environment with global fetch.');
  }

  const chargeId = payload.id;
  const subscriberHash = payload.customer.id; // Plan assumption: customer.id maps directly to subscriber_hash
  const baseUrl = `https://api.mailchimp.com/3.0/lists/${mailchimpListId}/members/${subscriberHash}/tags`;
  const authHeader = `Bearer ${mailchimpApiKey}`;

  // 1. GET existing tags to enforce "skip if tag exists" logic
  const getResponse = await fetch(baseUrl, {
    method: 'GET',
    headers: {
      Authorization: authHeader,
      'Content-Type': 'application/json',
    },
  });

  if (!getResponse.ok) {
    throw new Error(`GET ${baseUrl} failed with status ${getResponse.status}`);
  }

  const getData = (await getResponse.json()) as { tags?: Array<{ name: string; status: string }> };
  const existingTags = getData.tags ?? [];
  const tagAlreadyExists = existingTags.some(
    (tag) => tag.name === tagName && tag.status === 'active'
  );

  if (tagAlreadyExists) {
    return {
      tagAdded: false,
      chargeId,
      subscriberHash,
      tagName,
    };
  }

  // 2. POST to add the tag with Idempotency-Key = chargeId
  const postResponse = await fetch(baseUrl, {
    method: 'POST',
    headers: {
      Authorization: authHeader,
      'Content-Type': 'application/json',
      'Idempotency-Key': chargeId,
    },
    body: JSON.stringify({
      tags: [{ name: tagName, status: 'active' }],
    }),
  });

  if (!postResponse.ok) {
    throw new Error(`POST ${baseUrl} failed with status ${postResponse.status}`);
  }

  return {
    tagAdded: true,
    chargeId,
    subscriberHash,
    tagName,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, StripeChargeRefundedPayload, HandleResult } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures';

// Contract test — must remain at top level with title exactly 'contract'
describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeChargeRefundedPayload, {
      mailchimpApiKey: 'test-api-key',
      mailchimpListId: 'test_list_id',
      fetch,
    } as ConnectorConfig);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.tagAdded).toBe(true);
    expect(result.chargeId).toBe('ch_1234567890');
    expect(result.subscriberHash).toBe('cus_1234567890');
    expect(result.tagName).toBe('refunded');
  });
});

describe('handle', () => {
  const validConfig: ConnectorConfig = {
    mailchimpApiKey: 'test-api-key',
    mailchimpListId: 'test_list_id',
    tagName: 'refunded',
  };

  const validPayload: StripeChargeRefundedPayload = {
    id: 'ch_1234567890',
    customer: { id: 'cus_1234567890' },
  };

  it('happy path: adds tag when not present, returns correct result', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/tags')) {
        return jsonResponse({ tags: [{ name: 'other-tag', status: 'active' }] });
      }
      if (req.method === 'POST' && req.url.includes('/tags')) {
        expect(req.json).toEqual({ tags: [{ name: 'refunded', status: 'active' }] });
        expect(req.headers.get('idempotency-key')).toBe('ch_1234567890');
        expect(req.headers.get('authorization')).toBe('Bearer test-api-key');
        return jsonResponse({}, 200);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(validPayload, { ...validConfig, fetch });
    expect(result).toEqual({
      tagAdded: true,
      chargeId: 'ch_1234567890',
      subscriberHash: 'cus_1234567890',
      tagName: 'refunded',
    });
    expect(calls).toHaveLength(2);
    expect(calls[0].method).toBe('GET');
    expect(calls[1].method).toBe('POST');
  });

  it('skips POST when tag already exists on subscriber', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/tags')) {
        return jsonResponse({ tags: [{ name: 'refunded', status: 'active' }] });
      }
      return jsonResponse({ error: 'should not POST' }, 404);
    });

    const result = await handle(validPayload, { ...validConfig, fetch });
    expect(result.tagAdded).toBe(false);
    expect(calls).toHaveLength(1);
    expect(calls[0].method).toBe('GET');
  });

  it('uses custom tagName from config', async () => {
    const customTag = 'custom-refund-tag';
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ tags: [] });
      if (req.method === 'POST') {
        expect(req.json).toEqual({ tags: [{ name: customTag, status: 'active' }] });
        return jsonResponse({}, 200);
      }
      return jsonResponse({}, 404);
    });

    const result = await handle(validPayload, { ...validConfig, tagName: customTag, fetch });
    expect(result.tagName).toBe(customTag);
    expect(result.tagAdded).toBe(true);
    expect(calls[1].json).toEqual({ tags: [{ name: customTag, status: 'active' }] });
  });

  it('throws descriptive error when payload.id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const badPayload = { customer: { id: 'cus_123' } } as unknown as StripeChargeRefundedPayload;
    await expect(handle(badPayload, { ...validConfig, fetch })).rejects.toThrow(
      'Missing required field: id (Stripe charge ID)'
    );
  });

  it('throws descriptive error when payload.customer.id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const badPayload = { id: 'ch_123' } as unknown as StripeChargeRefundedPayload;
    await expect(handle(badPayload, { ...validConfig, fetch })).rejects.toThrow(
      'Missing required field: customer.id (Stripe customer ID)'
    );
  });

  it('throws when mailchimpApiKey is missing from config', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    await expect(handle(validPayload, { ...validConfig, mailchimpApiKey: '', fetch })).rejects.toThrow(
      'Missing config: mailchimpApiKey'
    );
  });

  it('throws when mailchimpListId is missing from config', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    await expect(handle(validPayload, { ...validConfig, mailchimpListId: '', fetch })).rejects.toThrow(
      'Missing config: mailchimpListId'
    );
  });

  it('throws on non-2xx GET response with status and endpoint', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401));
    await expect(handle(validPayload, { ...validConfig, fetch })).rejects.toThrow(
      'GET https://api.mailchimp.com/3.0/lists/test_list_id/members/cus_1234567890/tags failed with status 401'
    );
  });

  it('throws on non-2xx POST response with status and endpoint', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ tags: [] });
      return jsonResponse({ error: 'conflict' }, 409);
    });
    await expect(handle(validPayload, { ...validConfig, fetch })).rejects.toThrow(
      'POST https://api.mailchimp.com/3.0/lists/test_list_id/members/cus_1234567890/tags failed with status 409'
    );
  });

  it('sends Authorization header as Bearer token on both requests', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ tags: [] });
      if (req.method === 'POST') return jsonResponse({}, 200);
      return jsonResponse({}, 404);
    });

    await handle(validPayload, { ...validConfig, fetch });
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-api-key');
    expect(calls[1].headers.get('authorization')).toBe('Bearer test-api-key');
  });

  it('sends Idempotency-Key header equal to charge ID on POST only', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ tags: [] });
      if (req.method === 'POST') {
        expect(req.headers.get('idempotency-key')).toBe('ch_1234567890');
        return jsonResponse({}, 200);
      }
      return jsonResponse({}, 404);
    });

    await handle(validPayload, { ...validConfig, fetch });
    expect(calls[0].headers.get('idempotency-key')).toBeNull();
    expect(calls[1].headers.get('idempotency-key')).toBe('ch_1234567890');
  });

  it('maps customer.id to subscriber_hash in URL path', async () => {
    const customCustomerId = 'cus_abcdef123456';
    const payload: StripeChargeRefundedPayload = { id: 'ch_111', customer: { id: customCustomerId } };
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ tags: [] });
      if (req.method === 'POST') return jsonResponse({}, 200);
      return jsonResponse({}, 404);
    });

    await handle(payload, { ...validConfig, fetch });
    const expectedPath = `/lists/test_list_id/members/${customCustomerId}/tags`;
    expect(calls[0].url).toContain(expectedPath);
    expect(calls[1].url).toContain(expectedPath);
  });
});

# Stripe Refund → Mailchimp Tag Connector

Adds a "refunded" tag to a Mailchimp subscriber when a Stripe `charge.refunded` webhook is received. The connector checks existing tags first and skips the operation if the tag is already present, ensuring idempotent behavior via the Stripe charge ID as an `Idempotency-Key` header.

## What it does

1. Receives a Stripe `charge.refunded` webhook payload (via your HTTP endpoint).
2. Extracts the charge ID (`id`) and customer ID (`customer.id`).
3. Calls Mailchimp **GET /lists/{list_id}/members/{subscriber_hash}/tags** to fetch current tags.
4. If the tag "refunded" (configurable) is not already active on the subscriber:
   - Calls Mailchimp **POST /lists/{list_id}/members/{subscriber_hash}/tags** with the tag.
   - Includes `Idempotency-Key: <charge_id>` header for safe retries.
5. Returns a result indicating whether the tag was added.

## Configuration

| Config Property | Environment Variable | Required | Description |
|-----------------|---------------------|----------|-------------|
| `mailchimpApiKey` | `MAILCHIMP_API_KEY` | Yes | Mailchimp API key used as Bearer token. |
| `mailchimpListId` | `MAILCHIMP_LIST_ID` | Yes | The Mailchimp audience (list) ID containing the subscriber. |
| `tagName` | — | No | Tag name to add. Default: `"refunded"`. |
| `fetch` | — | No | Injected `fetch` implementation (for testing or non-browser runtimes). |

## Usage Example

```typescript
import { handle, ConnectorConfig, StripeChargeRefundedPayload } from './connector';

// In your webhook handler (e.g., Express, Fastify, Cloudflare Worker):
app.post('/stripe-webhook', async (req, res) => {
  const payload = req.body as StripeChargeRefundedPayload;
  const config: ConnectorConfig = {
    mailchimpApiKey: process.env.MAILCHIMP_API_KEY!,
    mailchimpListId: process.env.MAILCHIMP_LIST_ID!,
  };

  try {
    const result = await handle(payload, config);
    res.json({ success: true, ...result });
  } catch (err) {
    console.error('Connector error:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});
```

## Assumptions & Notes

- **Subscriber identification**: The plan assumes `customer.id` from the Stripe payload maps directly to the Mailchimp `subscriber_hash` (MD5 of lowercase email). This connector uses the Stripe customer ID as the `subscriber_hash` path parameter. If your Mailchimp subscribers are keyed differently, you must transform the ID before calling `handle`.
- **Tag name**: The default tag is `"refunded"`. Override via `config.tagName` if needed.
- **Idempotency**: The Stripe charge ID is sent as `Idempotency-Key` on the POST request. Mailchimp's API honors this header for safe retries.
- **Skip-if-exists**: A GET request fetches current tags before any POST. If the tag already exists with `status: "active"`, the POST is skipped and `tagAdded: false` is returned.
- **Error handling**: Non-2xx responses from Mailchimp throw an `Error` including the HTTP status and endpoint URL.
- **No inbound auth**: Stripe webhook signature verification is assumed to be handled by your HTTP layer (e.g., `stripe.webhookEndpoints` middleware). This connector does not verify signatures.
- **Pagination**: The Mailchimp "get member tags" endpoint does not paginate; all tags are returned in one response.
- **Environment**: Requires a global `fetch` (Node 18+, browsers, Cloudflare Workers, etc.) or an injected `fetch` via config.

